const SOURCE='https://raw.githubusercontent.com/SubmitGame/awesome-decomp-games/main/';
const labels={'static-recomp':'RECOMPILAÇÃO','source-port':'PORT NATIVO','engine-remake':'RECRIAÇÃO DE ENGINE','browser-port':'PORT PARA NAVEGADOR','browser-emulation':'EMULAÇÃO NO NAVEGADOR','browser-demo':'DEMONSTRAÇÃO / NOTÍCIA'};
const knownPorts=['HarbourMasters/Shipwright','HarbourMasters/2ship2harkinian','coop-deluxe/sm64coopdx','OpenGOAL/jak-project','HarbourMasters/Starship'];
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let games=[],limit=24,busy=false,favorites=new Set(),lastData=null;
let curated=typeof CURATED_PROJECTS!=="undefined"?CURATED_PROJECTS.map(g=>({...g})):[];
try{favorites=new Set(JSON.parse(localStorage.getItem('atlas-favorites')||'[]'))}catch{}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function safeURL(value){try{const u=new URL(value);return u.protocol==='https:'?u.href:''}catch{return ''}}
function date(s){if(!s||!Number.isFinite(Date.parse(s)))return 'não informada';return new Date(s).toLocaleDateString('pt-BR')}
function platforms(g){return (g.platform||'Não informada').split(/\s*\/\s*/).map(s=>s.trim()).filter(Boolean)}
const browserProjects=typeof BROWSER_PROJECTS!=='undefined'?BROWSER_PROJECTS:[];
function canonicalURL(value){const url=safeURL(value);if(!url)return '';const u=new URL(url);return (u.origin.replace('://www.', '://')+u.pathname.replace(/\/+$/, '')).toLowerCase()}
function mergeBrowserProjects(entries){
 let merged=[...entries];
 for(const extra of browserProjects){
   const urls=new Set([extra.url,...(extra.aliases||[]),extra.links.play].map(canonicalURL).filter(Boolean));
   const matches=g=>g.id===extra.id||(extra.repo&&g.repo?.toLowerCase()===extra.repo.toLowerCase())||urls.has(canonicalURL(g.url));
   const base=merged.find(matches);
   merged=merged.filter(g=>!matches(g));
   // Editorial links, status and classification must never be replaced by upstream data.
   // Repository releases cannot establish browser availability.
   merged.push({...base,...extra,release:null,release_url:null,last_commit:base?.last_commit,stars:base?.stars,direct:false,browser:true});
 }
 return merged;
}
function normalized(data){if(!Array.isArray(data.games)||!data.generated_at)throw Error('Base inválida');return mergeCatalog(data).filter(g=>g.browser ? !!(safeURL(g.url)&&labels[g.type]) : g.repo&&!/android|ios port/i.test(g.repo+" "+g.title)&&/^https:\/\/github\.com\/[^/]+\/[^/]+/.test(g.url)&& (['static-recomp','source-port','engine-remake'].includes(g.type)||knownPorts.some(r=>r.toLowerCase()===g.repo.toLowerCase()))).map(g=>({...g,type:labels[g.type]?g.type:'source-port'}))}
function mergeCatalog(data){
 const entries=new Map(data.games.filter(g=>typeof g.repo==='string').map(g=>[g.repo.toLowerCase(),g]));
 for(const extra of curated){
   const key=extra.repo.toLowerCase(),base=entries.get(key);
   const newerBase=base&&Date.parse(data.generated_at)>Date.parse(extra.verified_at);
   entries.set(key,{...(newerBase?{...extra,...base}:{...base,...extra}),id:extra.id,title:extra.title,platform:extra.platform,type:extra.type,cover:extra.cover,top_pick:extra.top_pick,verified_at:extra.verified_at,direct:true});
 }
 return mergeBrowserProjects([...entries.values()]);
}
async function refreshCurated(){
 const results=await Promise.allSettled(curated.map(async g=>{
   const [repo,release]=await Promise.all([getJSON('https://api.github.com/repos/'+g.repo),getJSON('https://api.github.com/repos/'+g.repo+'/releases/latest')]);
   if(repo.full_name?.toLowerCase()!==g.repo.toLowerCase()||typeof release.tag_name!=='string'||!safeURL(release.html_url))throw Error('Resposta inválida');
   return {...g,stars:repo.stargazers_count,last_commit:repo.pushed_at,archived:repo.archived,release:release.tag_name,release_date:release.published_at,release_url:release.html_url,verified_at:new Date().toISOString()};
 }));
 let successes=0;
 results.forEach((r,i)=>{if(r.status==='fulfilled'){curated[i]=r.value;successes++}});
 if(successes){try{localStorage.setItem('replay-curated',JSON.stringify(curated))}catch{}}
 const status=$('#directStatus');if(status)status.textContent=successes===curated.length?'Projetos nativos complementares: GitHub consultado agora.':'Projetos nativos complementares: consulta indisponível; dados da última verificação.';
 if(lastData){games=normalized(lastData);$('#total').textContent=games.length.toLocaleString('pt-BR');makeFilters();render()}
}
function coverKey(s){return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\([^)]*\)|\[[^\]]*\]/g,'').replace(/\bthe\b/g,'').replace(/&/g,'and').replace(/[^a-z0-9]/g,'')}
function indexedCover(g){if(typeof COVER_INDEX==='undefined')return '';return platforms(g).map(p=>COVER_INDEX[p+'|'+coverKey(g.title)]).find(Boolean)||''}
function cover(g){if(g.cover&&/^covers\/[\w-]+\.png$/.test(g.cover))return g.cover;if(indexedCover(g))return indexedCover(g);const t=g.title.toLowerCase();if(t.includes('ocarina of time')&&!t.includes('3d'))return 'covers/zelda.png';if(t.includes("majora")&&!t.includes('3d'))return 'covers/majora.png';if(t.includes('super mario 64')&&!t.includes('ds'))return 'covers/mario.png';if(t.includes('star fox 64'))return 'covers/starfox.png';return ''}
function picture(g){return cover(g)||(g.screenshot&&/^[\w/-]+\.(jpg|png|webp)$/.test(g.screenshot)?SOURCE+g.screenshot:'')||safeURL(g.thumb_src)||safeURL(g.og_image)||fallbackPoster(g)}
function fallbackPoster(g){const title=String(g.title||'Projeto');const short=title.length>26?title.slice(0,23)+'…':title;const platform=String(g.platform||'PC').split('/')[0].trim();const escSvg=x=>x.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');const svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 360"><defs><linearGradient id="b" x2="1" y2="1"><stop stop-color="#009b3a"/><stop offset="1" stop-color="#002776"/></linearGradient><pattern id="p" width="32" height="32" patternUnits="userSpaceOnUse"><path d="M0 31.5h32M31.5 0v32" stroke="#ffdf00" stroke-opacity=".12"/></pattern></defs><path fill="url(#b)" d="M0 0h640v360H0z"/><path fill="url(#p)" d="M0 0h640v360H0z"/><path d="M0 286 205 95l114 110 83-82 238 238H0z" fill="#061c37" fill-opacity=".58"/><circle cx="514" cy="93" r="47" fill="#ffdf00" fill-opacity=".92"/><path d="M501 68v50l39-25z" fill="#002776"/><text x="34" y="52" fill="#ffdf00" font-family="Arial,sans-serif" font-size="16" font-weight="700" letter-spacing="4">JOGOS RECOMPILADOS</text><text x="34" y="263" fill="#fff" font-family="Arial,sans-serif" font-size="30" font-weight="700">'+escSvg(short)+'</text><text x="36" y="310" fill="#fff" font-family="Arial,sans-serif" font-size="15" letter-spacing="3">'+escSvg(platform.toUpperCase())+' · ARTE ILUSTRATIVA</text></svg>';return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg)}
function platformFamily(p){if(/^(PS[1-5]|PSP|PlayStation)/.test(p))return 'PlayStation';if(/xbox/i.test(p))return 'Xbox';if(/^(N64|NES|SNES|GameCube|Game Boy|GBA|DS|3DS|Wii|Switch|Virtual Boy)/.test(p))return 'Nintendo';if(/Sega|Genesis|Dreamcast|32X|Saturn|Game Gear|Master System/.test(p))return 'Sega';if(/^(PC|DOS|Mac|Amiga|Commodore|ZX Spectrum)/.test(p))return 'Computadores';return 'Outras'}
function platformIcon(p){const handheld=/GBA|Game Boy|DS|PSP|Switch|Game Gear/.test(p);const pc=platformFamily(p)==='Computadores';return '<svg viewBox="0 0 32 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">'+(pc?'<rect x="4" y="2" width="24" height="16" rx="2"/><path d="M12 22h8m-4-4v4"/>':handheld?'<rect x="6" y="1" width="20" height="22" rx="4"/><rect x="10" y="4" width="12" height="9" rx="1"/><path d="M10 18h6m-3-3v6m7-3h1"/>':'<path d="M10 5h12c4 0 7 12 5 14s-5-2-7-4h-8c-2 2-5 6-7 4S6 5 10 5Z"/><path d="M9 10h6m-3-3v6m9-4h.1m3 3h.1"/>')+'</svg>'}
function filterPlatforms(){const query=($('#platformSearch')?.value||'').trim().toLowerCase();$$('.platform-option').forEach(el=>el.hidden=!el.dataset.platform.toLowerCase().includes(query));$$('.platform-group').forEach(group=>{group.hidden=![...group.querySelectorAll('.platform-option')].some(el=>!el.hidden);if(query&&!group.hidden)group.open=true});const empty=$('#platformEmpty');if(empty)empty.hidden=!query||$$('.platform-option').some(el=>!el.hidden)}
function makeFilters(){
 const checked=new Set($$('input[name=platform]:checked').map(e=>e.value)),opened=new Set($$('.platform-group[open]').map(e=>e.dataset.family));const counts={};games.forEach(g=>platforms(g).forEach(p=>counts[p]=(counts[p]||0)+1));$('#platformTotal').textContent=Object.keys(counts).length;
 $('#platforms').innerHTML=['PlayStation','Xbox','Nintendo','Sega','Computadores','Outras'].map(family=>{const entries=Object.entries(counts).filter(([p])=>platformFamily(p)===family).sort((a,b)=>b[1]-a[1]);if(!entries.length)return '';const open=opened.has(family)||entries.some(([p])=>checked.has(p))||(!opened.size&&family==='Nintendo');return '<details class="platform-group" data-family="'+family+'" '+(open?'open':'')+'><summary>'+family+' <small>'+entries.length+'</small></summary><div class="platform-tiles">'+entries.map(([p,n])=>'<label class="platform-option" data-platform="'+esc(p)+'"><input name="platform" type="checkbox" value="'+esc(p)+'" '+(checked.has(p)?'checked':'')+'><span class="platform-icon">'+platformIcon(p)+'</span><span class="platform-name">'+esc(p)+'</span><small>'+n+' projetos</small></label>').join('')+'</div></details>'}).join('');filterPlatforms();
}
function filtered(){const q=$('#search').value.trim().toLowerCase(),ps=$$('input[name=platform]:checked').map(e=>e.value),ts=$$('input[name=type]:checked').map(e=>e.value);return games.filter(g=>(!q||`${g.title} ${g.repo||''} ${g.publisher||''} ${g.description||''}`.toLowerCase().includes(q))&&(!ps.length||platforms(g).some(p=>ps.includes(p)))&&(!ts.length||ts.includes(g.type))&&(!$('#released').checked||g.release)&&(!$('#browserOnly')?.checked||g.browser)&&(!$('#browserPlayable')?.checked||g.browser&&safeURL(g.links?.play))&&(!$('#favorites').checked||favorites.has(g.id))).sort((a,b)=>{switch($('#sort').value){case'name':return a.title.localeCompare(b.title,'pt-BR');case'updated':return (Date.parse(b.last_commit)||0)-(Date.parse(a.last_commit)||0);case'stars':return (b.stars||0)-(a.stars||0);default:return (a.top_pick||99999)-(b.top_pick||99999)||(b.stars||0)-(a.stars||0)}})}
function cardLinks(g){
 if(!g.browser)return '<a class="github" href="'+esc(safeURL(g.url))+'" target="_blank" rel="noopener noreferrer">GitHub ↗</a><a class="details" href="'+esc(safeURL(g.release_url)||safeURL(g.url)+'/releases')+'" target="_blank" rel="noopener noreferrer">Releases ↗</a>';
 return [['play','Jogar'],['video','Vídeo'],['news','Notícia'],['code','Código']].filter(([key])=>safeURL(g.links?.[key])).map(([key,label])=>'<a class="resource-link '+key+'" href="'+esc(safeURL(g.links[key]))+'" target="_blank" rel="noopener noreferrer"'+(key==='code'&&g.code_note?' title="'+esc(g.code_note)+'"':'')+'>'+label+' ↗</a>').join('');
}
function render(){const all=filtered();$('#resultCount').innerHTML=`<b>${all.length.toLocaleString('pt-BR')}</b> projetos encontrados`;$('#savedCount').textContent=favorites.size;$('#empty').hidden=all.length>0;$('#more').hidden=all.length<=limit;$('#grid').innerHTML=all.slice(0,limit).map(g=>{const img=picture(g);return `<article class="card"><div class="card-art"><a class="project-cover" href="${esc(safeURL(g.url))}" target="_blank" rel="noopener noreferrer" aria-label="Abrir ${esc(g.title)} — projeto ou fonte"><span class="image-fallback" ${img?'hidden':''}>${esc(g.title.substring(0,2).toUpperCase())}</span>${img?`<img src="${esc(img)}" alt="${cover(g)?'Capa':'Imagem do projeto'}: ${esc(g.title)}" class="${cover(g)?'box':''}" loading="lazy">`:''}</a><span class="platform-badge">${esc(g.platform||'Plataforma não informada')}</span><button class="favorite" data-id="${esc(g.id)}" aria-label="${favorites.has(g.id)?'Remover dos':'Adicionar aos'} favoritos: ${esc(g.title)}" aria-pressed="${favorites.has(g.id)}">${favorites.has(g.id)?'♥':'♡'}</button></div><div class="card-body"><span class="type-tag ${g.type==='source-port'?'port':g.type==='engine-remake'?'engine':''}">${labels[g.type]}</span>${g.browser&&g.type==='static-recomp'?'<span class="browser-badge">NAVEGADOR</span>':''}<h3><a class="project-title" href="${esc(safeURL(g.url))}" target="_blank" rel="noopener noreferrer">${esc(g.title)}</a></h3><div class="repo" title="${esc(g.repo||g.publisher||'Projeto comunitário') }">${esc(g.repo||g.publisher||'Projeto comunitário')}</div>${g.browser?`<p class="project-description">${esc(g.description)}</p><p class="project-status">${esc(g.status)}</p><details class="project-limits"><summary>Limitações e requisitos</summary><p>${esc(g.limitations)}</p>${g.code_note?`<p>${esc(g.code_note)}</p>`:''}</details>`:`<div class="card-meta"><span class="release" title="${esc(g.release||'Sem release identificada')}">${g.archived?'◌ Arquivado':g.release?'● '+esc(g.release):'◌ Sem release'}</span><span>☆ ${Number(g.stars||0).toLocaleString('pt-BR',{notation:'compact'})}</span></div>`}<div class="card-links">${cardLinks(g)}</div>${g.browser?`<div class="direct-source">Fontes conferidas em ${date(g.verified_at)} · gameplay não testado</div>`:`<div class="repo" style="margin-top:12px">Última atividade: ${date(g.last_commit)}</div>`}${g.direct?`<div class="direct-source">GitHub oficial · verificado em ${date(g.verified_at)}</div>`:""}</div></article>`}).join('');$$('.project-cover img').forEach(img=>img.addEventListener('error',()=>{img.hidden=true;img.previousElementSibling.hidden=false},{once:true}))}
function apply(data,label){lastData=data;games=normalized(data);$('#total').textContent=games.length.toLocaleString('pt-BR');makeFilters();render();$('#syncLabel').textContent=label;$('#syncDate').textContent='Dados da fonte: '+date(data.generated_at)}
async function getJSON(url){const r=await fetch(url,{cache:'no-cache',signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error('Fonte indisponível');return r.json()}
async function refresh(){if(busy)return;busy=true;$('#refresh').disabled=true;$('#syncLabel').textContent='Consultando atualizações…';const directTask=refreshCurated();try{const data=await getJSON(SOURCE+'data/games.json');normalized(data);apply(data,'Sincronizado com a base');try{localStorage.setItem('atlas-catalog',JSON.stringify(data))}catch{}}catch{if(games.length){$('#syncLabel').textContent='Sem conexão com a fonte';$('#syncDate').textContent=lastData?'Dados da fonte: '+date(lastData.generated_at)+' · cópia disponível':'Usando os projetos disponíveis'}else{$('#resultCount').textContent='Não foi possível carregar o catálogo. Tente atualizar.'}}finally{try{await directTask}catch{const status=$('#directStatus');if(status)status.textContent='Não foi possível atualizar os projetos complementares.'}finally{busy=false;$('#refresh').disabled=false}}}
function reset(){ $$('aside input').forEach(e=>e.checked=false);$('#search').value='';if($('#platformSearch'))$('#platformSearch').value='';filterPlatforms();$('#sort').value='featured';limit=24;render()}
async function init(){try{const saved=JSON.parse(localStorage.getItem('replay-curated')||'[]');curated=curated.map(g=>{const cached=saved.find(s=>s.repo===g.repo);return cached&&Date.parse(cached.verified_at)>Date.parse(g.verified_at)?{...g,stars:cached.stars,last_commit:cached.last_commit,archived:cached.archived,release:cached.release,release_date:cached.release_date,release_url:cached.release_url,verified_at:cached.verified_at}:g})}catch{}let data;try{data=JSON.parse(localStorage.getItem('atlas-catalog')||'null');if(data)normalized(data)}catch{data=null}try{const bundled=await getJSON('catalog.json');if(!data||Date.parse(bundled.generated_at)>Date.parse(data.generated_at))data=bundled}catch{}if(data)apply(data,'Cópia disponível • buscando atualizações');await refresh()}
$('#search').addEventListener('input',()=>{limit=24;render()});$('#platformSearch')?.addEventListener('input',filterPlatforms);$('aside').addEventListener('change',()=>{limit=24;render()});$('#sort').addEventListener('change',()=>{limit=24;render()});$('#clear').onclick=reset;$('#resetEmpty').onclick=reset;$('#more').onclick=()=>{limit+=24;render()};$('#refresh').onclick=refresh;
$('#grid').addEventListener('click',e=>{const b=e.target.closest('.favorite');if(!b)return;favorites.has(b.dataset.id)?favorites.delete(b.dataset.id):favorites.add(b.dataset.id);try{localStorage.setItem('atlas-favorites',JSON.stringify([...favorites]))}catch{$('#toast').textContent='Favoritos disponíveis apenas nesta sessão.';$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}render()});
$('#savedNav').onclick=()=>{$('#favorites').checked=!$('#favorites').checked;limit=24;render();$('#catalogo').scrollIntoView({behavior:'smooth'})};['#aboutBtn','#sourcesBtn','#footerAbout'].forEach(s=>$(s).onclick=()=>$('#about').showModal());$('.close').onclick=()=>$('#about').close();$('#about').addEventListener('click',e=>{if(e.target===$('#about')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#about').open){e.preventDefault();$('#search').focus()}});setInterval(()=>{if(!document.hidden)refresh()},30*60*1000);init();
